   347|function resolveSendBranch(
   348|  deliveryBranch: DeliveryBranchStatus['branch'],
   349|  runtimeSource: RuntimeDebugSnapshot['source'],
   350|  httpStatus: string,
   351|): SendBranchProofRow {
   352|  if (deliveryBranch === 'not_observed') {
   353|    return { branch: null, label: 'pending', context: 'no send observed' };
   354|  }
   355|
   356|  const statusFragment = httpStatus !== 'pending' && httpStatus !== 'none' ? ` · ${httpStatus}` : '';
   357|
   358|  if (deliveryBranch === 'remote_db_insert') {
   359|    if (runtimeSource === 'remote_api' || runtimeSource === 'local_app_brain') {
   360|      return { branch: 'primary_realtime', label: 'primary_realtime', context: `assistant db insert${statusFragment}` };
   361|    }
   362|    if (runtimeSource === 'provider_fallback') {
   363|      return { branch: 'alternate_shared', label: 'alternate_shared', context: `gateway db insert${statusFragment}` };
   364|    }
   365|    return { branch: 'primary_realtime', label: 'primary_realtime', context: `db insert · source ${runtimeSource}${statusFragment}` };
   366|  }
   367|
   368|  if (deliveryBranch === 'local_fallback') {
   369|    return { branch: 'snapshot_fallback', label: 'snapshot_fallback', context: `local fallback path${statusFragment}` };
   370|  }
   371|
   372|  if (deliveryBranch === 'auth_session_failure') {
   373|    return { branch: 'local_only', label: 'local_only', context: `auth/session unavailable${statusFragment}` };
   374|  }
   375|
   376|  return { branch: 'local_only', label: 'local_only', context: `unresolved branch${statusFragment}` };
   377|}
